"use strict";(globalThis.webpackChunktiennhm_github_io=globalThis.webpackChunktiennhm_github_io||[]).push([[743],{50789:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/10/02/github-nofollow","metadata":{"permalink":"/notes/2026/10/02/github-nofollow","source":"@site/notes/2026-10-02-github-nofollow.md","title":"GitHub g\u1eafn nofollow v\xe0o m\u1ecdi link ra ngo\xe0i","description":"K\u1ec3 c\u1ea3 tr\u01b0\u1eddng website \u1edf sidebar repo. Backlink t\u1eeb GitHub kh\xf4ng truy\u1ec1n th\u1ea9m quy\u1ec1n t\xean mi\u1ec1n.","date":"2026-10-02T00:00:00.000Z","tags":[{"inline":false,"label":"Git & GitHub","permalink":"/notes/tags/git","description":"Ghi ch\xe9p ng\u1eafn v\u1ec1 Git, GitHub v\xe0 quy tr\xecnh l\xe0m vi\u1ec7c quanh ch\xfang."},{"inline":false,"label":"SEO","permalink":"/notes/tags/seo","description":"Ghi ch\xe9p ng\u1eafn v\u1ec1 ch\u1ec9 m\u1ee5c, canonical, backlink v\xe0 h\xe0nh vi c\u1ee7a b\u1ed9 m\xe1y t\xecm ki\u1ebfm."}],"hasTruncateMarker":false,"authors":[{"name":"Nguy\u1ec5n Hu\u1ef3nh Minh Ti\u1ebfn","title":"Fullstack Developer @ Utop.io","url":"https://github.com/TienNHM","imageURL":"/img/tiennhm-avatar.jpg","key":"tiennhm","page":null}],"frontMatter":{"title":"GitHub g\u1eafn nofollow v\xe0o m\u1ecdi link ra ngo\xe0i","description":"K\u1ec3 c\u1ea3 tr\u01b0\u1eddng website \u1edf sidebar repo. Backlink t\u1eeb GitHub kh\xf4ng truy\u1ec1n th\u1ea9m quy\u1ec1n t\xean mi\u1ec1n.","authors":["tiennhm"],"tags":["git","seo"]},"unlisted":false,"nextItem":{"title":"S\u01a1 \u0111\u1ed3 Mermaid sai c\xfa ph\xe1p kh\xf4ng l\xe0m \u0111\u1ecf build","permalink":"/notes/2026/10/01/mermaid-khong-lam-do-build"}},"content":"H\xf4m nay soi Google Search Console th\u1ea5y \u0111\xfang **3 backlink** tr\u1ecf v\u1ec1 site, c\u1ea3 ba t\u1eeb `github.com` v\xe0 `github.io`. M\u1edf HTML trang repo ra xem th\xec:\\n\\n```html\\n<a href=\\"http://tiennhm.io.vn/\\" rel=\\"noopener noreferrer nofollow\\">\\n```\\n\\nGitHub g\u1eafn `rel=\\"nofollow\\"` v\xe0o **m\u1ecdi** link ra ngo\xe0i, k\u1ec3 c\u1ea3 tr\u01b0\u1eddng *Website* \u1edf sidebar repo \u2014 ch\u1ed7 ai c\u0169ng t\u01b0\u1edfng l\xe0 backlink ngon nh\u1ea5t m\xecnh c\xf3.\\n\\nNgh\u0129a l\xe0 ba backlink \u0111\xf3 **kh\xf4ng truy\u1ec1n th\u1ea9m quy\u1ec1n** g\xec h\u1ebft. V\u1ec1 m\u1eb7t x\u1ebfp h\u1ea1ng, site \u0111ang \u1edf v\u1ea1ch xu\u1ea5t ph\xe1t.\\n\\n\u0110i\u1ec1u n\xe0y \u0111\u1ed5i h\u1eb3n c\xe1ch \u0111\u1ecdc m\u1ed9t v\u1ee5 t\u1ee5t hi\u1ec3n th\u1ecb: n\u1ebfu nghi do \\"m\u1ea5t backlink khi \u0111\u1ed5i t\xean mi\u1ec1n\\" th\xec n\xean ki\u1ec3m `rel` tr\u01b0\u1edbc, v\xec r\u1ea5t c\xf3 th\u1ec3 ch\u1eb3ng c\xf3 g\xec \u0111\u1ec3 m\xe0 m\u1ea5t.\\n\\nGi\xe1 tr\u1ecb th\u1eadt c\u1ee7a link GitHub l\xe0 **ng\u01b0\u1eddi th\u1eadt b\u1ea5m v\xe0o**, kh\xf4ng ph\u1ea3i PageRank."},{"id":"/2026/10/01/mermaid-khong-lam-do-build","metadata":{"permalink":"/notes/2026/10/01/mermaid-khong-lam-do-build","source":"@site/notes/2026-10-01-mermaid-khong-lam-do-build.md","title":"S\u01a1 \u0111\u1ed3 Mermaid sai c\xfa ph\xe1p kh\xf4ng l\xe0m \u0111\u1ecf build","description":"Mermaid render \u1edf tr\xecnh duy\u1ec7t, n\xean l\u1ed7i ch\u1ec9 hi\u1ec7n th\xe0nh h\u1ed9p \u0111\u1ecf tr\xean trang. C\xe1ch b\u1eaft t\u1ea1i ch\u1ed7.","date":"2026-10-01T00:00:00.000Z","tags":[{"inline":false,"label":"C\xf4ng c\u1ee5","permalink":"/notes/tags/cong-cu","description":"M\u1eb9o v\xe0 ph\xe1t hi\u1ec7n nh\u1ecf v\u1ec1 c\xf4ng c\u1ee5 l\u1eadp tr\xecnh h\u1eb1ng ng\xe0y."},{"inline":false,"label":"Ki\u1ec3m th\u1eed","permalink":"/notes/tags/kiem-thu","description":"Ghi ch\xe9p ng\u1eafn v\u1ec1 ki\u1ec3m th\u1eed v\xe0 c\xe1c l\u1edbp ki\u1ec3m tra t\u1ef1 \u0111\u1ed9ng."}],"hasTruncateMarker":false,"authors":[{"name":"Nguy\u1ec5n Hu\u1ef3nh Minh Ti\u1ebfn","title":"Fullstack Developer @ Utop.io","url":"https://github.com/TienNHM","imageURL":"/img/tiennhm-avatar.jpg","key":"tiennhm","page":null}],"frontMatter":{"title":"S\u01a1 \u0111\u1ed3 Mermaid sai c\xfa ph\xe1p kh\xf4ng l\xe0m \u0111\u1ecf build","description":"Mermaid render \u1edf tr\xecnh duy\u1ec7t, n\xean l\u1ed7i ch\u1ec9 hi\u1ec7n th\xe0nh h\u1ed9p \u0111\u1ecf tr\xean trang. C\xe1ch b\u1eaft t\u1ea1i ch\u1ed7.","authors":["tiennhm"],"tags":["tools","testing"]},"unlisted":false,"prevItem":{"title":"GitHub g\u1eafn nofollow v\xe0o m\u1ecdi link ra ngo\xe0i","permalink":"/notes/2026/10/02/github-nofollow"}},"content":"Docusaurus render Mermaid **\u1edf ph\xeda tr\xecnh duy\u1ec7t**. H\u1ec7 qu\u1ea3: m\u1ed9t s\u01a1 \u0111\u1ed3 sai c\xfa ph\xe1p v\u1eabn build xanh, v\u1eabn deploy, v\xe0 ch\u1ec9 hi\u1ec7n th\xe0nh h\u1ed9p b\xe1o l\u1ed7i \u0111\u1ecf khi c\xf3 ng\u01b0\u1eddi m\u1edf \u0111\xfang trang \u0111\xf3.\\n\\nB\u1eaft t\u1ea1i ch\u1ed7 \u0111\u01b0\u1ee3c, d\xf9 h\u01a1i v\xf2ng. `mermaid.parse()` c\u1ea7n DOM (n\xf3 g\u1ecdi DOMPurify), nh\u01b0ng **l\u1ed7i ng\u1eef ph\xe1p \u0111\u01b0\u1ee3c n\xe9m ra tr\u01b0\u1edbc b\u01b0\u1edbc \u0111\xf3**:\\n\\n```js\\nconst mermaid = (await import(\'mermaid\')).default;\\ntry {\\n  await mermaid.parse(code);\\n} catch (err) {\\n  const msg = String(err.message);\\n  // Ch\u1ec9 l\u1ed7i c\xfa ph\xe1p m\u1edbi \u0111\xe1ng quan t\xe2m; l\u1ed7i DOMPurify l\xe0 do thi\u1ebfu DOM.\\n  if (/parse error|syntax error|expecting/i.test(msg)) report(msg);\\n}\\n```\\n\\nM\u1ed9t chi ti\u1ebft su\xfdt l\xe0m t\xf4i tin nh\u1ea7m: l\u1ea7n ti\xeam l\u1ed7i th\u1eed nghi\u1ec7m \u0111\u1ea7u ti\xean **kh\xf4ng \u0103n**, v\xec chu\u1ed7i t\xf4i ch\xe8n v\u1eabn n\u1eb1m trong d\u1ea5u nh\xe1y n\xean v\u1eabn h\u1ee3p l\u1ec7. Ph\u1ea3i d\xf9ng ngo\u1eb7c vu\xf4ng kh\xf4ng \u0111\xf3ng m\u1edbi ra l\u1ed7i th\u1eadt.\\n\\nChecker lu\xf4n xanh th\xec v\xf4 d\u1ee5ng. Lu\xf4n th\u1eed l\xe0m n\xf3 \u0111\u1ecf tr\u01b0\u1edbc khi tin n\xf3."}]}}')}}]);